{
  "implementation": "def solve(case):
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    trans = case['transitions']
    state = initial
    trace = []
    step = 0
    final_value = None
    while step < max_steps:
        node = trans[state]
        if node['kind'] == 'final':
            final_value = node['value']
            break
        action = node['action']
        observation = tool_obs[action]
        next_state = node['next_by_observation'].get(observation, node['default_next'])
        trace.append({
            'step': step,
            'state': state,
            'action': action,
            'observation': observation
        })
        state = next_state
        step += 1
    else:
        node = trans[state]
        if node['kind'] == 'final':
            final_value = node['value']
    if final_value is not None:
        status = 'success'
    else:
        status = 'max_steps_exceeded'
    return {
        'final': final_value,
        'status': status,
        'trace': trace
    }"
}
